#!/usr/bin/env python3
r"""WAVE 4 -- export the ROM tables the player port reads, from the DECRYPTED
:maincpu image, into `games/ddpdoj/rip/port/` (gitignored, twice over).

NOTHING ROM-DERIVED IS EVER COMMITTED (docs/worklog/README.md rule 1).  The
port's *code* is ours and is committed; the numbers it indexes are the
cartridge's and are regenerated by this tool from a ROM the runner owns.

Every table below is cited by ROM address and by the instruction that reads it,
so a second person can check any entry without re-deriving the addressing:

  $2552DC  16 bytes   stick nibble -> ANGLE byte.  Read at $2495B4
                      `move.b (A2,D0.w),($1b,A6)` with D0 = ($18,A6) & $f.
                      $FF = "no direction" (the `bpl` at $2495BA takes the
                      no-move path).  MEASURED values: ff 00 20 ff 30 38 28 ff
                      10 08 18 ff ff ff ff ff.
  $2418B4  256 words  ANGLE-FOLD table.  Read at $241830
                      `adda.w (A0,D3.w),A3` with D3 = (angle & $3f) * 8, i.e.
                      word index angle*4.  It is a triangle wave 0,8,...,$200,
                      $1F8,...,0 -- it folds the full circle onto ONE quadrant
                      of 65 entries, which is why the quadrant negation at
                      $241850/$241870/$241890/$2418B0 is not a double count.
  $200920  N longs    SPEED-LEVEL pointer table.  Read at $241820
                      `movea.l (A3,D0.w),A3` with D0 = speedIndex * 4.
                      Entry s points at $200D20 + $208*s.
  ...each              65 entries x {dx:int32, dy:int32}, ONE QUADRANT, 0 deg
                      (dx=r, dy=0) to 90 deg (dx=0, dy=r).  Read at $241836
                      `move.l (A3)+,D2 / move.l (A3)+,D3`, then `asr.l #4`.
                      Speed 0's table is all zeros (a real "do not move").
  $2552EC  16 bytes   the knockback ramp read at $2496B2 `move.w (A0,D0.w),D0`
                      with D0 = ($46,A6).  Only reached when bit 7 of the
                      player's ($1,A6) is set; UNPORTED path, exported for the
                      record.
  $25533A / $2553CA   the two ANIMATION pointer tables read at the handler's
                      tail $249E4E: `movea.l (A0,D0.w),A0` with D0 =
                      shipType*2, then `move.l (A0,D0.w),($a,A6)` with
                      D0 = tilt ($4e,A6), which steps by 4 over [-$20,+$20].
                      So 17 longs centred on the pointer.

  python export-tables.py            write rip/port/player.tables.json
  python export-tables.py --verify   re-read and check the invariants only
"""
from __future__ import annotations

import hashlib
import json
import struct
import sys
from pathlib import Path

HERE = Path(__file__).resolve().parent
IMAGE = HERE / "oracle" / "out" / "maincpu.bin"
OUT = HERE.parent / "rip" / "port"
RIP = HERE.parent / "rip"                 # WAVE 27D: rip/sound + rip/rom
KEYON_TSV = RIP / "sound" / "keyon.tsv"   # the C4 sample-inventory aid
U17_FILE = "cave_m04401b032.u17"          # 4 MiB sample ROM (sound wave D)
U17_ROM = RIP / "rom" / U17_FILE

DIR_TABLE = 0x2552DC          # 16 bytes
FOLD_TABLE = 0x2418B4         # 256 words
SPEED_PTRS = 0x200920         # longs
QUAD_ENTRIES = 65             # 0..90 degrees inclusive
QUAD_STRIDE = QUAD_ENTRIES * 8    # $208
KNOCKBACK = 0x2552EC          # 16 bytes
# The frame-rate GOVERNOR's four PC-relative word tables, read at $23C2B4 /
# $23C2E4 (pairs indexed by $813096) and $23C342 / $23C332 (single words indexed
# by $813094).  See src/framesync.js.
GOV_TABLES = {"t23C3EE": (0x23C3EE, 10), "t23C402": (0x23C402, 10),
              "t23C416": (0x23C416, 5), "t23C420": (0x23C420, 5)}
ANIM_A = 0x25533A
ANIM_B = 0x2553CA
TILT_MIN, TILT_MAX, TILT_STEP = -0x20, 0x20, 4
SCAN_CAP = 512                # see speed_levels(): a scan cap, not the table end

# --------------------------------------------------------------------- WAVE 8
# THE SHOT SUBSYSTEM'S ROM.  Wave 4 exported hand-picked tables as JSON arrays.
# The shot spawn ($249BFC -> $24A222) does not read TABLES, it copies a 38-byte
# RECORD TEMPLATE and then follows three more pointers out of it, so the honest
# export is a set of ROM WINDOWS the port reads the way the 68000 does -- with a
# bounds check that THROWS BY ADDRESS on any read the export did not cover,
# instead of an array index that would silently return undefined.
#
# Each window is here because an instruction reads inside it; the comment names
# the instruction.  Windows are deliberately a little wider than the bytes we
# know are used, because "wider than measured" fails loudly at the export and
# "narrower than used" fails at runtime on the player's machine.
SHOT_WINDOWS = [
    (0x25321E, 0x0040, "W164 player-death partial palette row tables, P1/P2"),
    (0x2551FA, 0x0006, "W164 death-reset formation cap bytes for formations 2/4/6"),
    (0x255B7C, 0x009C, "W164 death animation pointer list through its FFFFFFFF terminator"),
    (0x252B42, 0x008E, "W163 hyper rank-power tables including power-zero reads"),
    (0x25531C, 0x001E, "W163 hyper pending and request mode tables"),
    (0x2866D2, 0x000C, "W163 chain cap stock adjustment table"),
    (0x286EC2, 0x0014, "W163 normal and active chain cap earn tables"),
    (0x2874E0, 0x004C, "W163 hyper end-flash sprite table"),
    (0x27F0FA, 0x009C, "W163 hyper-item motion table through next data boundary"),
    # $249C3E lea $2554EA / $249C88 lea $255502 / $249D5E lea $25551A -- the
    # per-FORMATION pointer tables, and the per-POWER tables they point at
    # ($255532..$2555A9, five longs each at a TWO-byte stride, so the power word
    # must be even -- the same trap as the ship selector).
    (0x2554E0, 0x0100, "$2554EA/$255502/$25551A + the $255532.. power tables"),
    # $249C1A `move.w (A2),D7` with A2 = the LONG at $8127E4 -- a ROM pointer
    # the game stores in RAM at ship select.  MEASURED $25523C, holding 4.  The
    # window is here because the port throws by address if $8127E4 ever points
    # anywhere else, which is exactly what happened the first time it ran.
    (0x255200, 0x0100, "the $8127E4 shot-count words at $25523C.."),
    # $24A222's template: 38 bytes copied field by field into the shot record.
    # $24DA20..$24DB9B is the ten SHOT templates (2 tables x 5 powers).
    (0x24D8A0, 0x0360, "shot templates $24DA20.. + the $24D8AC/$24D918 anim tables"),
    # ...and the LASER templates plus their anim tables.
    (0x24E740, 0x0320, "laser templates $24E8BC.. + $24E744/$24E7D4"),
    # The $25551A family's templates and anim tables ($24DFE8/$24E054 and
    # $24EEA4/$24EF34).  Not reached by the player's own spawn; reached by a
    # SEEDED option-pod shot, whose ($1a,A6) the handlers feed to $241D34.
    (0x24DFE0, 0x0300, "$25551A[0] templates $24E15C.. + $24DFE8/$24E054"),
    (0x24EEA0, 0x0360, "$25551A[1] templates $24F01C.. + $24EEA4/$24EF34"),
    # The OPTION PODS' pointer tables and templates ($24D4E2's $24D2FC/$24D35C).
    (0x24D2E0, 0x00E0, "$24D2FC/$24D35C + their per-power tables"),
    (0x24F400, 0x0C00, "option-pod templates $24F8EC.. and every anim table they point at"),
    (0x251100, 0x0300, "option-pod laser templates $251184.."),
    # $253B72 lea $24DDD6 / $253C7A lea $24DEB2 -- the per-($26,A6) tables the
    # handlers re-point the record's sprite fields from, and their structs.
    (0x24DDD0, 0x01B0, "$24DDD6 and $24DEB2 + the structs they point at"),
    # $253E5A lea $24FC8E
    (0x24FC80, 0x0100, "$24FC8E + its structs"),
    # $253F38 lea $25014C
    (0x250140, 0x0100, "$25014C + its structs"),
    # $241D46 lea ($241AF4,PC) -- the SECOND angle-fold table.  256 words,
    # indexed by the WHOLE angle byte (D3 = D1*2), not by angle&$3f*4 like
    # $2418B4.  Same triangle, different stride: do not alias the two.
    (0x241AF4, 0x0200, "$241AF4 the shot vector's angle-fold table"),
    # $2433C2 lea ($2433D0,PC) -- the 64-longword pseudo-random table.
    (0x2433D0, 0x0100, "$2433D0 the $2433AE pseudo-random longword table"),
    # W31: $2433AE IS ONE OF A FAMILY.  A scan of the whole decrypted image for
    # `addq.b #1,$803917` finds 32 sites in build B, each reading a DIFFERENT
    # canned table off the SAME 8-bit counter.  The stage-1 midboss $26B6FA
    # uses two of them, so their tables are windows now.
    #   $2431F4: `moveq #$3f` masks the index -> 64 bytes, $24324E..$24328D,
    #            and $24328E is the next routine's `addq.b` (far end PINNED).
    (0x24324E, 0x0040, "W31: $2431F4's 64-byte draw table $24324E, indexed by "
                       "$803916 & $3F (the midboss's $26B2AC draws)"),
    #   $242FDE: NO MASK -- `move.w $803916,D0` then `move.b (A0,D0.w),D0` --
    #            so the index is the whole word.  256 bytes, $24301A..$243119,
    #            and $24311A is code (far end PINNED).  In range only because
    #            $23BE36 `clr.w $803916` zeroes the high byte and `addq.b`
    #            never carries into it.
    (0x24301A, 0x0100, "W31: $242FDE's 256-byte draw table $24301A, indexed by "
                       "the WHOLE $803916 word (the midboss's $26B2AC/$26B35E)"),
    # ------------------------------------------------------------- WAVE 12
    # THE SHIP'S OWN SPRITE BLOCK ($24A482) and the OPTION OBJECT ($24C096).
    # One window covers every table both of them index, because they are packed
    # together in $2553xx..$2559xx and splitting them would be a schema decision
    # the ROM does not support.  Named individually so a reader can check any
    # one of them:
    #   $25533A the ship IMAGE pointer table (17 longs per ship, tilt-indexed)
    #   $2553CA the ship's X HALF-EXTENTS -> $2553F2 (NOT animation; see below)
    #   $25545A the ship SHADOW sprite table, read at $249ECE
    #   $255672 the aura's flip/colour words, read at $24A4D0 with ($57,A6)*2
    #   $25567A the aura's 16 sprite longs, read at $24A4BA with ($28,A6)
    #   $2556BA/$255676 their ($1,A6)-bit-7 twins ($24A4F2/$24A510) -- UNREACHED
    #   $2556E2 the glow's per-ship/per-tilt sprite tables ($24A55C)
    #   $255882 ...and their stick-down variant ($24A576) -- UNREACHED
    #   $255A22 the glow's {protection bias, dx, size} struct ($24A562)
    #   $255A36 ...and its variant ($24A57C) -- UNREACHED
    (0x255330, 0x0900, "WAVE 12: $25533A/$2553CA/$25545A/$255672/$25567A/"
                       "$2556BA/$2556E2/$255882/$255A22/$255A36 -- every table "
                       "the ship's draw block $24A482 and its shadow $249EA0 read"),
    # $24C0D2 lea ($24BBAA,PC) / movea.l (A0,D0.w),A0 with D0 = (($5a,A4)-2)*2.
    # MEASURED entries: $24BF6E, $24BFC8, $24C022, each 90 bytes of template.
    # The window runs to $24C07C = $24C022 + 90.
    (0x24BBA0, 0x04E0, "WAVE 12: $24BBAA + the three option TEMPLATES it points "
                       "at ($24BF6E/$24BFC8/$24C022, 90 bytes each)"),
    # ------------------------------------------------------------- WAVE 13
    # THE SCROLL PROGRAM.  `src/background.js` reads all of this the way the
    # 68000 does; every base below is the address of an instruction's operand.
    #
    #   $240D62  the five per-stage TILE BASES, added whole to every map
    #            longword ($240D80 lea ($240D62,PC),A0 / adda.w $813096)
    (0x240D60, 0x0020, "WAVE 13: $240D62 the five per-stage BG tile bases"),
    #   $261252  BG palette block ptrs  ($2611B2)
    #   $261266  BG column-stream ptrs  ($2611D6)
    #   $26153E  the five script PAIRS  ($26152C)
    #   $26157A  stage-1 object stream, 22 entries + $FFFFFFFF ($2620E4)
    #   $261602  stage-1 cue stream, 14 B ($262186)
    #   $261610.. all TEN scripts, 186 records, ending at $261F6E ($262072)
    (0x261240, 0x0D40, "WAVE 13: $261252/$261266/$26153E + the object and cue "
                       "streams + all ten scroll scripts ($261610..$261F6E)"),
    #   $262302  the five BG-element handler tables, and the tables themselves
    #            ($262328 / $26224A..$26227D for stage 1).  Read by op $10 so
    #            the unported-note can NAME the constructor W18 must port.
    (0x262240, 0x0100, "WAVE 13: $26224A..$2622F2 the BG-element handler "
                       "tables and $262302 the per-stage pointer table"),
    # W168. Stage 2's eight constructors and six updater bodies are one closed
    # contiguous code family. The last updater reads the adjacent 32-pair
    # animation table at $262A4C..$262B4B, so code and data are inseparable.
    (0x2627AC, 0x03A0, "W168: all 8 stage-2 BGELEM constructors/updaters plus "
                       "the closed 32-pair animation table $262A4C..$262B4B"),
    #   $225B78  STAGE 1's column stream, 248 columns x 36 B.  Stages 2..5 are
    #            deliberately NOT exported: this wave validated stage 1 and a
    #            read of another stage's stream must be a LOUD THROW BY ADDRESS
    #            rather than a plausible picture.  The next four streams run
    #            $228658/$22A5F8/$22B1E8/$22D770 (recon §2) and are W15's.
    (0x225B78, 0x22E0, "WAVE 13: the STAGE-1 BG column stream, 248 columns "
                       "x 36 B = 8,928 B ($2611D6 -> $26135A)"),
    # ------------------------------------------------------------- WAVE 20
    # THE AIM PAIR.  One window per core, because the two cores' tables are
    # packed contiguously and splitting them by name would be a schema decision
    # the ROM does not support (the same reasoning as the WAVE 12 block above).
    #   $2420C6  8 longs   the octant SIGN dispatch ($24209C jmp) -- each entry
    #                      is $2420AE (sub) or $2420BA (add) and src/aim.js
    #                      CHECKS that rather than trusting an index
    #   $2420E6  8 words   the octant BASE ($242092)
    #   $2420F6  129 bytes THE ARCTAN LUT ($242088).  NOT formula-reconstructible:
    #                      it deviates from a true arctan by +1.65 units of 512
    #                      at index 10 (20-recon-aiming §2), in the near-axis
    #                      band, which is where most shots live.  Ship the bytes.
    (0x2420C0, 0x0100, "WAVE 20: aim64's three tables -- $2420C6 octant signs, "
                       "$2420E6 octant bases, $2420F6 the 129-byte arctan LUT"),
    #   $242312  8 x 8 B   the octant stubs ($24230A jsr (A0,D4.w)), each
    #                      <add|sub>.w D0,D1 / andi.w #$FF,D1 / rts
    #   $242352  8 words   the octant BASE ($2422F6)
    #   $242362  65 bytes  the aim256 LUT ($2422EC)
    (0x242300, 0x0100, "WAVE 20: aim256's tables -- $242312 octant stubs, "
                       "$242352 bases, $242362 the 65-byte LUT"),
    # THE ENEMY TYPE TABLE.  256 entries x 8 bytes in TWO halves, split at type
    # $80 -- `census.py entry()`, and the split is why one window will not do.
    # Every entry is (init, handler) and EVERY init is an 8-byte stub whose body
    # is at init+8 (20-recon-enemy-census: 256 of 256, verified mechanically).
    (0x267820, 0x0410, "WAVE 20: the enemy type table, types $00..$7F "
                       "($267824, 8 bytes per type: init, handler)"),
    (0x27E410, 0x0410, "WAVE 20: the enemy type table, types $80..$FF ($27E412)"),
    # THE TWO TURRET TYPES' PROTOTYPES.  $2637A2 copies the SUB-record prototype
    # ($20 bytes per sub-record) and $26377A copies D0+1 words into ($16,A5).
    # Only the two types this wave validates are exported: a read of any other
    # type's prototype must be a LOUD THROW BY ADDRESS, not a plausible enemy.
    (0x268180, 0x0080, "WAVE 20: type $10's record prototype $268192 (16 words, "
                       "$2680E0 moveq #$F) and sub-record prototype $2681B2"),
    (0x268800, 0x0060, "WAVE 20: type $11's record prototype $268808 (16 words, "
                       "$26872E moveq #$F) and sub-record prototype $268828"),
    # THE 32-DIRECTION TURRET SPRITE TABLES, read at $2683B6 / $268A4E with the
    # facing rounded by `addq.b #1,D1 / andi.w #$3E,D1 / add.w D1,D1`.  The
    # windows also carry the 16-entry MUZZLE table $268B1E ($268AEC) and the
    # 16-direction body tables $268594 / $268B9E ($26831E / $2689B6).
    (0x268580, 0x01A0, "WAVE 20: type $10's $268594 (16 dir body) and $268694 "
                       "(32 dir turret) sprite tables"),
    (0x268B10, 0x0220, "WAVE 20: type $11's $268B1E muzzle table, $268B9E body "
                       "table and $268C9E 32-direction turret sprite table"),
    # ------------------------------------------------------------- WAVE 21
    # THE ENEMY BULLET PATTERN GENERATORS.  src/bullets.js and
    # src/bulletmath.js read every one of these the way the 68000 does.
    #
    #   $281956  39 longs   the TEMPLATE pointer table ($281564 movea.l (A1,D0.w))
    #   $2819F4  39 x $14   the templates themselves, ending at $281CD6 where
    #                       code begins ($4A79 tst.w abs.l).  The extent is
    #                       pinned from BOTH ends: entry[39] of the pointer
    #                       table is $018100, not a pointer.
    (0x281950, 0x0390, "WAVE 21: $281956 the 39 bullet-KIND template pointers "
                       "and the 39 x 20-byte templates at $2819F4..$281CD5"),
    #   $2815C6  39 longs   the SPAWN-INIT pointer table ($2815B6 adda.w D0,A1)
    (0x2815C0, 0x00B0, "WAVE 21: $2815C6 the 39 spawn-init pointers "
                       "(nine distinct routines)"),
    #   $282030  39 longs   the BEHAVIOUR pointer table ($281F16 adda.w D0,A0).
    #                       The BODIES are not ported by wave 21; the table is
    #                       exported so `behaviourFor` can name the address it
    #                       is not running.
    (0x282030, 0x00A0, "WAVE 21: $282030 the 39 behaviour-initialiser pointers"),
    #   $283F50  256 words  THE FOLD TABLE ($2841A2 lea ($283F50,PC),A2 /
    #                       adda.w (A2),A3).  MEASURED to be exactly
    #                       8*triangle(i), period 128, peak 64 -- so 256
    #                       directions fold onto 65 quarter-angle records.
    (0x283F50, 0x0200, "WAVE 21: $283F50 the 256-word direction FOLD table"),
    #   $283D4C  32 entries x 12 B  the MUZZLE-OFFSET + sprite table the shared
    #                       behaviour helper $2820CC indexes by
    #                       ((dir+4)&$F8)*3/2 (kinds 0/1/7/8/12/13/...). Each
    #                       entry is {posOffset long, descriptor long, attr word};
    #                       the posOffset's two signed halves (each >>1) are added
    #                       to posA/posB at spawn. 32 dir-buckets x 12 = 384 B;
    #                       the byte at $283ECC is `add.w D0,D0` (next routine).
    (0x283D4C, 0x0180, "WAVE 26: $283D4C the 32-entry direction muzzle-offset "
                      "table read by $2820CC (bullet behaviour spawn helper)"),
    #   $283C4C  32 words  the direction-sprite OFFSET table the shared epilogue
    #                       $283C0E indexes by ((dir+4)>>2)&$3E (kinds 7/...).
    #                       Sprite-only (selects a renderOffs frame); 64 B.
    (0x283C4C, 0x0040, "WAVE 26: $283C4C the 32-word direction-sprite offset "
                      "table read by the $283C0E behaviour epilogue"),
    #   $2822EC  32 words  the direction-sprite OFFSET table the OTHER shared
    #                       epilogue, $2822AE, indexes by (dir+4)&$F8. Note this
    #                       is a DIFFERENT table from $283C4C above and a
    #                       different index expression -- $2822AE masks to $F8
    #                       where $283C0E shifts >>2 and masks $3E. 64 B.
    #
    #   W26 transcribed $2822AE but NO KIND DISPATCHED TO IT, so this window was
    #   never needed and never noticed to be missing. W27's kinds 2 and 21 are
    #   the first to reach it, and the port threw immediately and by address --
    #   `UNPORTED $2822FC: word outside every ROM window`. That throw is the
    #   system working: the alternative to a missing window is invented data.
    #
    #   SIZE CORRECTION (W27, same day): this window was first added as $40
    #   bytes, on the assumption "32 words = 64 bytes". WRONG. $2822AE indexes
    #   it as `move.w ($2822EC,A1,D0),D1` with D0 = (dir+4)&$F8, so D0 is a BYTE
    #   OFFSET running 0, 8, 16 ... $F8 -- the 32 entries are spaced 8 bytes
    #   apart, not packed. The last one lives at $2822EC+$F8, so the table needs
    #   $FA bytes, and it ends exactly where kind 3's body begins ($2823EC), so
    #   $100 is the true extent.
    #
    #   It passed anyway, because every test written against this table used
    #   `dir: 0x10` -> D0 = $10 -> well inside $40. The first test to use
    #   dir $40 threw `UNPORTED $28232C` on its first frame. A window validated
    #   only by inputs that all happen to be small is not validated.
    (0x2822EC, 0x0100, "WAVE 27: $2822EC the 32-entry direction-sprite offset "
                      "table read by the $2822AE behaviour epilogue; indexed by "
                      "(dir+4)&$F8 as a BYTE offset, so it spans $100 to $2823EC"),
    #   $2821FA  kind 2's sprite-frame table: 9 pointers into $28221E..$2822AC,
    #                       each of which is a list of $1BFxxx frame descriptors.
    #                       $2822AE resolves *(A0 + $2822EC[d0]) then
    #                       *(that + index). Covers both indirections: $2821FA
    #                       through the end of the pointer lists at $2822AC.
    (0x2821FA, 0x00B4, "WAVE 27: $2821FA kind 2's dir-indexed sprite-frame "
                      "pointer table + the frame lists it points into"),
    #   $282C8E  kind 21's equivalent of $2821FA. Same shape, same two-level
    #                       indirection, different frames.
    (0x282C8E, 0x00B4, "WAVE 27: $282C8E kind 21's dir-indexed sprite-frame "
                      "pointer table + the frame lists it points into"),
    #   $283704  kind 33's 6-entry descriptor ring, read by $2836E2 as
    #                       `lea $283704(pc),A0 / adda.w D0,A0 / move.l (A0),$a`
    #                       with D0 = the WORD at record +$2C.
    #
    #   SIZED FROM THE INDEX EXPRESSION, not the entry count. The initialiser
    #   seeds +$2C = $14 and the continuation does `subq.w #$4 / bcc /
    #   move.w #$C`, so the reachable indices are $14, $10, $C, $8, $4, $0 --
    #   the highest is $14 and the read is a LONGWORD, so the extent is $18.
    #   $283704 + $18 = $28371C, exactly where kind 34's body begins: an
    #   abutting bound, the same evidence used for $2822EC's $100.
    #   $2830EA  kind 26's 9-entry dir-indexed sprite-frame table, reached
    #                       through the $283C8C epilogue (`lea $2830EA(pc),A0`
    #                       then `adda.w $283C4C[d1],A0 / move.l (A0),$a`).
    #
    #   REQUIRED, not sprite-only: $283C46 also writes +$10 = frame + (+$14),
    #   and kind 26's CONTINUATION uses +$10 as its ring limit.  Without the
    #   window the ring bound is unavailable, not merely the picture.
    #
    #   Sized from the index expression: the $283C4C offsets top out at $20
    #   (measured, not assumed -- the 32 words are 0,4,8...$20 and back down),
    #   the read is a longword, so the extent is $24.  $2830EA + $24 = $28310E,
    #   exactly where kind 26's continuation begins: an abutting bound.
    (0x2830EA, 0x0024, "WAVE 27: $2830EA kind 26's 9-entry dir-indexed sprite-"
                      "frame table, read by the $283C8C epilogue; also supplies "
                      "the +$10 ring limit its continuation compares against"),
    (0x283704, 0x0018, "WAVE 27: $283704 kind 33's 6-entry descriptor table, "
                      "indexed by the word at record +$2C ($14 down to 0, then "
                      "wrapping to $C -- a 2-entry lead-in over a 4-entry ring)"),
    #   $282714  kind 7's 9-entry dir-indexed sprite-frame table, read by the
    #                       $283C0E epilogue (`lea $282714(pc),A0 / bra $283C0E`
    #                       then `adda.w $283C4C[d1],A0 / move.l (A0),$a`).
    #
    #   WAVE 52 ADDED THIS WINDOW AND IT IS A CONSEQUENCE, NOT AN OVERSIGHT.
    #   `src/mover.js` ran the $283C0E epilogue only `if (ctx.sprites)` -- and
    #   until W52 nothing ever passed a sprite sink, so the read never happened
    #   and the missing window could not be reached.  Wiring the enemy bullets'
    #   emit reached it on the first run: `UNPORTED $282718` at step 1,417.
    #
    #   Sized exactly like $2830EA above and for the same reason: the $283C4C
    #   offsets top out at $20 (the 32 words are 0,4,8..$20 and back down) and
    #   the read is a longword, so the extent is $24.  $282714 + $24 = $282738,
    #   which is kind 7's own CONTINUATION -- an abutting bound, the same
    #   evidence $2830EA and $2822EC are sized by.
    (0x282714, 0x0024, "WAVE 52: $282714 kind 7's 9-entry dir-indexed sprite-"
                      "frame table, read by the $283C0E epilogue. Reachable "
                      "only once a sprite sink exists (W52)"),
]

# WAVE 21 -- THE VELOCITY FIELD, exported in full and here is why.
#
# `$284190` indexes `$200920` with a BYTE from record +$1A, so the domain is
# 0..255 and nothing narrows it: the speed a bullet gets is
# `template base (20) + the call site's bias + $813160 + $812950`, and the last
# two are LIVE VARIABLES ($252C8E writes $812950 every single frame).  A derived
# subset -- the trick `speed_index_set()` plays for the player's own shots -- is
# a guess here, and a guess that fails on a player's machine rather than at
# export time.  The table's extent is proven from both ends: the pointer table
# is an exact arithmetic progression for exactly 256 entries (entry 256 and its
# two neighbours are 0), and the last quadrant table ends at $221520, the next
# known data object.  So: one window, $200920..$22151F, 134,144 bytes.
VELOCITY_FIELD = (0x200920, 0x221520 - 0x200920,
                  "WAVE 21: the WHOLE velocity field -- $200920's 256 longword "
                  "pointers and the 256 x 65 x 8-byte quadrant tables they "
                  "point at, $200D20..$22151F")
SHOT_WINDOWS.append(VELOCITY_FIELD)

# WAVE 27 SOUND B -- THE Z80 PROGRAM UPLOAD SOURCE.  The Z80 has 64 KiB RAM and
# NO ROM (pgm.cpp:29); the 68k uploads its whole program through the $C10000
# shared window early in boot.  The upload source is a verbatim, stride-1 copy
# sitting in the decrypted 68k image at $2C348A, length $5B98 (23448 bytes):
# copying it into the Z80 RAM model matches rip/sound/z80ram.bin byte-for-byte
# across the code region $0086-$5B97 (23314 bytes), with exactly 31 differences
# ALL in the volatile scratch $0000-$0085 (set by reset/init, never part of the
# uploaded program text).  See docs/worklog/ddpdoj/138-impl-sound-wave-b.md.
# The port reconstructs the Z80 program from THIS window; z80ram.bin is the
# byte-match ORACLE only (gitignored, never shipped).
Z80_UPLOAD_LEN = 0x5B98  # 23448. NOTE: $5B98 = 23448, not the 23416 some old
                         # briefs carried (23416 = $5B78). The hex figure wins.
Z80_UPLOAD = (0x2C348A, Z80_UPLOAD_LEN,
              "WAVE 27B: the Z80 program upload source -- verbatim, stride 1. "
              "Read into the Z80 RAM model by src/z80.js uploadZ80Program(). "
              "Code region $0086-$5B97 matches rip/sound/z80ram.bin exactly.")
SHOT_WINDOWS.append(Z80_UPLOAD)

# WAVE 158 -- THE COMPLETE STATIC ICS2115 SAMPLE DATA UNION OF u17.
#
# W157 statically walked all 69 driver-valid SFX descriptors and every score
# selector/event reachable from all 11 cues.  That inventory reaches 159/160
# BGM descriptors and 69+159 exact playback intervals.  Their conservative
# corrected command union is 6 disjoint half-open byte runs, including OscEnd and the adjacent
# interpolation byte.  Captured keyons validate it in both directions but do
# not define it: 1,620/1,620 dynamic episodes belong to this static set, while
# 175/228 static descriptor intervals were absent from the stage-1 capture.
#
# All reachable banks are 4..7, hence only `cave_m04401b032.u17` is needed;
# `pgm_m01s.rom` has zero reachable descriptor witnesses.  The owner approved
# this near-full global deferred shard on 2026-08-08.  It remains a stitched
# non-contiguous semantic asset with no full-ROM runtime fallback.
U17_SAMPLE_BASE = 0x400000  # u17's load address in the ICS 24-bit sample space
# Half-open u17 file intervals [lo, hi), mechanically copied from W157's
# descriptor-derived checker.  Do not add one: `hi` already includes OscEnd
# plus its interpolation neighbour.
_SAMPLE_INTERVALS = [
    (0x000000, 0x0DB837), (0x0DB935, 0x0DC257),
    (0x0E1853, 0x0FFFE1),
    (0x100000, 0x1FFFF6),
    (0x200000, 0x2FFBFA), (0x300000, 0x377BF2),
]
# (offset, length, why) -- length derived from the half-open bounds.
SAMPLE_WINDOWS = [
    (lo, hi - lo,
     f"W158 static sample frag {i + 1}/6 (u17 ${lo:06X}..${hi:06X}, "
     f"ICS ${lo + U17_SAMPLE_BASE:06X}-${hi + U17_SAMPLE_BASE:06X}; "
     "descriptor-derived through OscEnd and its interpolation neighbour).")
    for i, (lo, hi) in enumerate(_SAMPLE_INTERVALS)
]
# The union must be DISJOINT and SORTED, and total exactly this many bytes.
SAMPLE_UNION_RAW = 3_612_873

