    (0x2735F0, 0x0220, "W30: type $80's two fan-direction tables $2735FA "
                       "($2817B8 loop) and $2736FA ($2817A8 loop), 64 longs each"),
    # $27347A is indexed by `(D1 & $3E) * 2` -> 0..$7C, 32 longwords.  EXTENT
