                       "$285C86/$285E00) and rank-icon P1 table $2882A6.  W124 "
                       "CORRECTION: the P1 rank-icon table is 32 longwords "
                       "($1CA36C..$1CA008, $1c-delta), running $2882A6..$288326 "
                       "($80 bytes), NOT 8 -- the rank-icon index "
